input.content:
:root {
  --bg: #11251a;
  --bg-2: #193327;
  --panel: rgba(17, 34, 25, 0.9);
  --panel-alt: rgba(25, 51, 39, 0.92);
  --line: rgba(175, 225, 188, 0.22);
  --text: #ecf6ee;
  --muted: #b1d0ba;
  --accent: #8fe388;
  --accent-2: #f4d35e;
  --warning: #ffb347;
  --danger: #e76f51;
  --shadow: rgba(0, 0, 0, 0.28);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
  font-family: Arial, Helvetica, sans-serif;
  background: linear-gradient(180deg, var(--bg) 0%, #0d1d14 100%);
  color: var(--text);
}

body {
  min-height: 100vh;
  display: flex;
  align-items: stretch;
  justify-content: center;
  padding: 20px;
}

button {
  font: inherit;
}

.app-shell {
  width: min(1400px, 100%);
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 18px;
  box-shadow: 0 10px 30px var(--shadow);
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 18px 24px;
}

.eyebrow {
  margin: 0 0 6px;
  color: var(--accent);
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

h1, h2, h3, p {
  margin: 0;
}

h1 {
  font-size: clamp(1.8rem, 3vw, 2.8rem);
}

.header-stats {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.mini-stat {
  min-width: 120px;
  padding: 10px 14px;
  border-radius: 12px;
  background: rgba(255,255,255,0.04);
  border: 1px solid var(--line);
  text-align: center;
}

.mini-stat span {
  display: block;
  color: var(--muted);
  font-size: 0.72rem;
  margin-bottom: 4px;
}

.game-layout {
  display: grid;
  grid-template-columns: 290px minmax(0, 1fr) 320px;
  gap: 18px;
  min-height: 700px;
}

.sidebar, .forest-panel {
  padding: 18px;
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.stat-card {
  background: var(--panel-alt);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 12px 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.stat-card span {
  color: var(--muted);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.objective-box {
  background: rgba(255,255,255,0.03);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 14px 12px;
}

.label {
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-2);
  margin-bottom: 8px;
}

.objective-text {
  color: var(--muted);
  line-height: 1.5;
}

.progress-bar {
  overflow: hidden;
  width: 100%;
  height: 14px;
  margin-top: 14px;
  background: rgba(255,255,255,0.08);
  border-radius: 999px;
  border: 1px solid var(--line);
}

.progress-fill {
  height: 100%;
  width: 0%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--accent) 0%, var(--accent-2) 100%);
  transition: width 0.2s ease;
}

#goalProgressLabel {
  margin-top: 8px;
  color: var(--muted);
  font-size: 0.8rem;
}

.message-box {
  background: linear-gradient(180deg, rgba(143,227,136,0.12), rgba(255,255,255,0.02));
  border: 1px solid rgba(143,227,136,0.22);
  border-radius: 12px;
  padding: 12px 13px;
  color: var(--text);
  line-height: 1.45;
}

.forest-panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.forest-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}

.secondary-btn {
  background: rgba(255,255,255,0.05);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 10px 12px;
  cursor: pointer;
}

#forest {
  position: relative;
  flex: 1;
  display: grid;
  grid-template-columns: repeat(6, minmax(70px, 1fr));
  gap: 14px;
  padding: 14px;
  background: linear-gradient(180deg, rgba(130, 205, 145, 0.08), rgba(12, 26, 18, 0.5));
  border-radius: 16px;
  border: 1px solid var(--line);
  min-height: 560px;
  align-content: start;
}

.tree {
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  min-height: 150px;
  padding: 12px 6px 6px;
  border-radius: 12px;
  background: rgba(255,255,255,0.02);
  border: 1px solid transparent;
  cursor: pointer;
  user-select: none;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.tree:hover {
  transform: translateY(-2px);
  border-color: rgba(143,227,136,0.42);
}

.tree .trunk {
  position: absolute;
  bottom: 16px;
  width: 18px;
  height: 58px;
  border-radius: 7px;
  background: linear-gradient(180deg, #7a4f2d, #4b2d19);
  box-shadow: inset -3px 0 0 rgba(0,0,0,0.18);
}

.tree .crown {
  position: absolute;
  bottom: 62px;
  width: 72px;
  height: 58px;
  background: linear-gradient(180deg, var(--tree-color, #3b9d4d) 0%, #265b37 100%);
  border-radius: 50% 50% 45% 45%;
  box-shadow: inset 0 -8px 0 rgba(0,0,0,0.08);
}

.tree .crown::before, .tree .crown::after {
  content: "";
  position: absolute;
  background: inherit;
  border-radius: 50%;
}

.tree .crown::before {
  width: 52px;
  height: 52px;
  left: -10px;
  top: 8px;
}

.tree .crown::after {
  width: 46px;
  height: 46px;
  right: -10px;
  top: 10px;
}

.tree .tree-strength {
  position: absolute;
  top: 8px;
  left: 8px;
  right: 8px;
  text-align: center;
  font-size: 0.72rem;
  font-weight: bold;
  color: rgba(255,255,255,0.76);
}

.tree.chopped {
  opacity: 0.25;
  pointer-events: none;
}

.shop-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.shop-item {
  padding: 14px 12px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.03);
}

